# -*- coding: utf-8 -*-
"""Lecture 43 vignette pool A -- Pulmonary Nodules and Neoplasms (Gray): epidemiology, risk factors and spread
(slides 3-10), incidental nodules and presenting symptoms (slides 11-13), and diagnostic workup and biopsy
(slides 14-15).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md: the key names the decisive clue and the slide fact;
each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:".

Narration scope (cms_e7l43_scope.py): the slide 11 algorithm is asked with the probability class given in words
("very low", "low to moderate", "high"), never as a percentage; metastatic presentations come from slide 13, with
the adrenal finding keyed as adrenal (never "kidney") and hyponatremia WITH hyperkalemia and hypotension kept apart
from inappropriate antidiuretic hormone; the slide 15 biopsy pathway carries the "what instead" items (unfit for
lobectomy -> segmentectomy, unfit for surgery -> radiotherapy, biopsy unsafe -> treat without it). No adenocarcinoma
percentage and no women's mortality rank anywhere. He corrected no slide out loud, so nothing here keys a spoken
correction.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e7l43_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


